import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

// Push subscriptions, the reminders scheduled for them, and a log of what was sent.
// A device is one installed copy of the app; its id is a random secret generated by the app,
// so knowing it is what authorizes changes. There are no user accounts.

export type PushSubscriptionJSON = {
  endpoint: string;
  keys: { p256dh: string; auth: string };
};

export type Reminder = {
  /** Stable per device, e.g. "item-3-soon". */
  id: string;
  /** Unix time in milliseconds. */
  at: number;
  title: string;
  body: string;
  /** Path in the app to open when the notification is tapped. */
  url: string;
};

export type DueReminder = Reminder & { deviceId: string; subscription: PushSubscriptionJSON; attempts: number };

export type Device = {
  id: string;
  subscription: PushSubscriptionJSON;
  userAgent: string | null;
  createdAt: number;
  /** Last time the app sent its schedule, i.e. was opened. */
  lastSeenAt: number;
  reminders: number;
  nextReminderAt: number | null;
};

export type DeliveryKind = 'reminder' | 'test' | 'broadcast';

export type Broadcast = {
  id: number;
  at: number;
  title: string;
  body: string;
  url: string;
  sent: number;
  failed: number;
  gone: number;
};

export type Store = ReturnType<typeof openStore>;

// Each entry upgrades the schema by one version (PRAGMA user_version). Never edit a released entry.
const MIGRATIONS = [
  // 1: initial schema (databases created before migrations existed already have these tables).
  `CREATE TABLE IF NOT EXISTS device (
     id TEXT PRIMARY KEY,
     subscription TEXT NOT NULL,
     updated_at INTEGER NOT NULL
   );
   CREATE TABLE IF NOT EXISTS reminder (
     device_id TEXT NOT NULL REFERENCES device (id) ON DELETE CASCADE,
     id TEXT NOT NULL,
     at INTEGER NOT NULL,
     title TEXT NOT NULL,
     body TEXT NOT NULL,
     url TEXT NOT NULL,
     attempts INTEGER NOT NULL DEFAULT 0,
     PRIMARY KEY (device_id, id)
   );
   CREATE INDEX IF NOT EXISTS reminder_at ON reminder (at);`,
  // 2: device details for the admin dashboard, delivery log, broadcast history.
  `ALTER TABLE device ADD COLUMN created_at INTEGER;
   UPDATE device SET created_at = updated_at;
   ALTER TABLE device ADD COLUMN user_agent TEXT;
   CREATE TABLE delivery (
     at INTEGER NOT NULL,
     kind TEXT NOT NULL,
     ok INTEGER NOT NULL
   );
   CREATE INDEX delivery_at ON delivery (at);
   CREATE TABLE broadcast (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     at INTEGER NOT NULL,
     title TEXT NOT NULL,
     body TEXT NOT NULL,
     url TEXT NOT NULL,
     sent INTEGER NOT NULL,
     failed INTEGER NOT NULL,
     gone INTEGER NOT NULL
   );`,
];

const DELIVERY_LOG_DAYS = 90;

export function openStore(path: string) {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec('PRAGMA journal_mode = WAL; PRAGMA foreign_keys = ON;');
  migrate(db);

  const upsertDevice = db.prepare(
    `INSERT INTO device (id, subscription, updated_at, created_at, user_agent) VALUES (?, ?, ?, ?, ?)
     ON CONFLICT (id) DO UPDATE SET
       subscription = excluded.subscription, updated_at = excluded.updated_at, user_agent = excluded.user_agent`
  );
  const clearReminders = db.prepare('DELETE FROM reminder WHERE device_id = ?');
  const insertReminder = db.prepare(
    'INSERT INTO reminder (device_id, id, at, title, body, url) VALUES (?, ?, ?, ?, ?, ?)'
  );
  const deleteDeviceStmt = db.prepare('DELETE FROM device WHERE id = ?');
  const selectDue = db.prepare(
    `SELECT r.device_id, r.id, r.at, r.title, r.body, r.url, r.attempts, d.subscription
     FROM reminder r JOIN device d ON d.id = r.device_id
     WHERE r.at <= ? ORDER BY r.at LIMIT ?`
  );
  const deleteReminderStmt = db.prepare('DELETE FROM reminder WHERE device_id = ? AND id = ?');
  const bumpAttempts = db.prepare('UPDATE reminder SET attempts = attempts + 1 WHERE device_id = ? AND id = ?');
  const deviceQuery = (where: string) =>
    db.prepare(
      `SELECT d.id, d.subscription, d.user_agent, d.created_at, d.updated_at,
              COUNT(r.id) AS reminders, MIN(r.at) AS next_at
       FROM device d LEFT JOIN reminder r ON r.device_id = d.id
       ${where}
       GROUP BY d.id ORDER BY d.updated_at DESC`
    );
  const selectDevices = deviceQuery('');
  const selectDevice = deviceQuery('WHERE d.id = ?');
  const insertDelivery = db.prepare('INSERT INTO delivery (at, kind, ok) VALUES (?, ?, ?)');
  const pruneDeliveries = db.prepare('DELETE FROM delivery WHERE at < ?');
  const selectDeliveryStats = db.prepare(
    'SELECT kind, SUM(ok) AS ok, COUNT(*) - SUM(ok) AS failed FROM delivery WHERE at >= ? GROUP BY kind'
  );
  const countReminders = db.prepare('SELECT COUNT(*) AS n, MIN(at) AS next_at FROM reminder');
  const insertBroadcast = db.prepare(
    'INSERT INTO broadcast (at, title, body, url, sent, failed, gone) VALUES (?, ?, ?, ?, ?, ?, ?)'
  );
  const selectBroadcasts = db.prepare('SELECT * FROM broadcast ORDER BY at DESC LIMIT ?');

  function toDevice(row: Record<string, unknown>): Device {
    return {
      id: row.id as string,
      subscription: JSON.parse(row.subscription as string) as PushSubscriptionJSON,
      userAgent: (row.user_agent as string | null) ?? null,
      createdAt: row.created_at as number,
      lastSeenAt: row.updated_at as number,
      reminders: row.reminders as number,
      nextReminderAt: (row.next_at as number | null) ?? null,
    };
  }

  return {
    /** Saves the device's subscription and replaces its whole reminder schedule. */
    replaceSchedule(
      deviceId: string,
      subscription: PushSubscriptionJSON,
      reminders: Reminder[],
      { now = Date.now(), userAgent = null }: { now?: number; userAgent?: string | null } = {}
    ) {
      db.exec('BEGIN');
      try {
        upsertDevice.run(deviceId, JSON.stringify(subscription), now, now, userAgent?.slice(0, 300) ?? null);
        clearReminders.run(deviceId);
        for (const r of reminders) insertReminder.run(deviceId, r.id, r.at, r.title, r.body, r.url);
        db.exec('COMMIT');
      } catch (error) {
        db.exec('ROLLBACK');
        throw error;
      }
    },

    deleteDevice(deviceId: string): boolean {
      return deleteDeviceStmt.run(deviceId).changes > 0;
    },

    getDevice(deviceId: string): Device | null {
      const row = selectDevice.get(deviceId);
      return row ? toDevice(row) : null;
    },

    listDevices(): Device[] {
      return selectDevices.all().map(toDevice);
    },

    due(now: number, limit = 500): DueReminder[] {
      return selectDue.all(now, limit).map((row) => ({
        deviceId: row.device_id as string,
        id: row.id as string,
        at: row.at as number,
        title: row.title as string,
        body: row.body as string,
        url: row.url as string,
        attempts: row.attempts as number,
        subscription: JSON.parse(row.subscription as string) as PushSubscriptionJSON,
      }));
    },

    /** A reminder is deleted once delivered, so it can't be sent twice. */
    markSent(deviceId: string, id: string) {
      deleteReminderStmt.run(deviceId, id);
    },

    markFailed(deviceId: string, id: string) {
      bumpAttempts.run(deviceId, id);
    },

    logDelivery(kind: DeliveryKind, ok: boolean, now = Date.now()) {
      insertDelivery.run(now, kind, ok ? 1 : 0);
    },

    pruneDeliveryLog(now = Date.now()) {
      pruneDeliveries.run(now - DELIVERY_LOG_DAYS * 24 * 3600 * 1000);
    },

    deviceCount(): number {
      return (db.prepare('SELECT COUNT(*) AS n FROM device').get()!.n as number) ?? 0;
    },

    stats(since: number) {
      const reminders = countReminders.get()!;
      const delivered = Object.fromEntries(
        selectDeliveryStats.all(since).map((r) => [r.kind as string, { ok: r.ok as number, failed: r.failed as number }])
      ) as Partial<Record<DeliveryKind, { ok: number; failed: number }>>;
      return {
        devices: this.deviceCount(),
        scheduledReminders: reminders.n as number,
        nextReminderAt: (reminders.next_at as number | null) ?? null,
        delivered,
      };
    },

    saveBroadcast(b: Omit<Broadcast, 'id'>): number {
      return Number(insertBroadcast.run(b.at, b.title, b.body, b.url, b.sent, b.failed, b.gone).lastInsertRowid);
    },

    listBroadcasts(limit = 50): Broadcast[] {
      return selectBroadcasts.all(limit) as unknown as Broadcast[];
    },

    close() {
      db.close();
    },
  };
}

function migrate(db: DatabaseSync) {
  const current = db.prepare('PRAGMA user_version').get()!.user_version as number;
  for (let version = current; version < MIGRATIONS.length; version++) {
    db.exec('BEGIN');
    try {
      db.exec(MIGRATIONS[version]);
      db.exec(`PRAGMA user_version = ${version + 1}`);
      db.exec('COMMIT');
    } catch (error) {
      db.exec('ROLLBACK');
      throw error;
    }
  }
}
